const fs = require('fs');
const readline = require('readline');
const path = require('path');

const brainDir = 'C:/Users/admin/.gemini/antigravity-ide/brain';
const conversations = [
  'fe5f3da4-28e8-4953-b097-ce64bd94b483',
  '53b57104-e4e2-40d0-adc5-813cc565893f'
];

async function dumpViewCalls() {
  for (const conv of conversations) {
    const transcriptPath = path.join(brainDir, conv, '.system_generated', 'logs', 'transcript_full.jsonl');
    if (!fs.existsSync(transcriptPath)) continue;

    console.log(`\n=================== Transcript: ${conv} ===================`);
    const fileStream = fs.createReadStream(transcriptPath);
    const rl = readline.createInterface({
      input: fileStream,
      crlfDelay: Infinity
    });

    let lastViewCall = null;

    for await (const line of rl) {
      if (!line.trim()) continue;
      const step = JSON.parse(line);

      if (step.type === 'PLANNER_RESPONSE' && step.tool_calls) {
        step.tool_calls.forEach(toolCall => {
          const name = toolCall.name || toolCall.toolName;
          const args = toolCall.args || toolCall.arguments;
          if (name === 'view_file') {
            lastViewCall = {
              step_index: step.step_index,
              path: args.AbsolutePath,
              start: args.StartLine,
              end: args.EndLine
            };
          }
        });
      } else if (step.source === 'SYSTEM' && lastViewCall) {
        // This is the output of the tool call
        console.log(`[Step ${lastViewCall.step_index}] viewed ${lastViewCall.path} (lines ${lastViewCall.start}-${lastViewCall.end})`);
        const contentPreview = String(step.content).substring(0, 150).replace(/\r?\n/g, ' ');
        console.log(`  Preview: ${contentPreview}...`);

        // If it's purchase.js or csa.js, let's write the full text to a file
        if (lastViewCall.path.endsWith('purchase.js') || lastViewCall.path.endsWith('csa.js')) {
          const outPath = path.join(brainDir, '53b57104-e4e2-40d0-adc5-813cc565893f', 'scratch', `recovered_${path.basename(lastViewCall.path)}_${conv}_step_${lastViewCall.step_index}.txt`);
          fs.writeFileSync(outPath, String(step.content));
          console.log(`  Saved full content to ${outPath}`);
        }

        lastViewCall = null;
      } else {
        lastViewCall = null;
      }
    }
  }
}

dumpViewCalls().catch(err => {
  console.error(err);
});
